import fs from 'node:fs';
import path from 'node:path';

/**
 * What the builds of the projects share: one folder per example below `src/`, named by its id, and one module per
 * example below `generated/examples/`, which `@porsche-design-system/examples/<id>` re-exports.
 */

/** `components/button/form/story.ts` → `components/button/form`: the example a file below `src/` is part of. */
export const toExampleId = (file: string): string => path.dirname(file).split(path.sep).join('/');

/** The first line of every generated file. */
export const generatedHeader = (from: string): string => `// Generated by scripts/build.ts from ${from} – do not edit.`;

/** The ids as the members of a union type, `never` for none. */
export const toIdUnion = (ids: string[]): string => ids.map((id) => `  | '${id}'`).join('\n') || '  never';

/** The MDX source of an example's description, `example.mdx` in its folder. Fails for an empty one. */
export const readDescription = (srcDir: string, id: string, project: string): string | undefined => {
  const file = path.join(srcDir, id, 'example.mdx');
  if (!fs.existsSync(file)) {
    return undefined;
  }
  const description = fs.readFileSync(file, 'utf8');
  if (!description.trim()) {
    throw new Error(`[${project}] the example.mdx of "${id}" is empty; describe the example or remove the file`);
  }
  return description;
};

/**
 * Fails for a file below `src/` that belongs to no example: every folder holds one example, made of the files its
 * project allows (`allowed`, by id), and nothing else.
 */
export const assertExampleFolders = (
  srcDir: string,
  allowed: Readonly<Record<string, readonly string[]>>,
  project: string
): void => {
  const stray = fs
    .globSync('**/*', { cwd: srcDir, withFileTypes: true })
    .filter((entry) => entry.isFile())
    .map((entry) => path.relative(srcDir, path.join(entry.parentPath, entry.name)))
    .filter((file) => !allowed[toExampleId(file)]?.includes(path.basename(file)))
    .sort();
  if (stray.length) {
    throw new Error(`[${project}] files outside of an example:\n${stray.join('\n')}`);
  }
};

/** From `generated/examples/<id>.ts` up to `generated/`: `components/button/form` → `../../../`. */
export const toGeneratedDir = (id: string): string => '../'.repeat(id.split('/').length);

/** Writes the module of an example to `generated/examples/<id>.ts`. */
export const writeExampleModule = (generatedDir: string, id: string, lines: string[]): void => {
  const file = path.join(generatedDir, 'examples', `${id}.ts`);
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, `${lines.join('\n')}\n`);
};
